      "Одна из самых экспрессивных вещей архива. Сюжет — не вид, а сопротивление: искривлённые, узловатые сучья ползут по земле во все стороны, каждый написан плотным лилово-розовым мазком, и вместе они образуют почти графическую сеть поверх горячего цветового поля. Земля взята открытой охрой, киноварью и золотом — цвет северной осени, когда тундра действительно горит; поверх положены короткие красные и жёлтые касания, отчего поверхность вибрирует. Небо тёмное, глухое, сине-фиолетовое, и оно давит на всю эту раскалённую массу сверху. Никакого горизонта, никакого моря — только склон, дерево и небо. Художник, обычно сдержанный и точный, здесь пишет почти яростно, и вещь получилась самой напряжённой в северной серии. Подписана и датирована художником.",
