    descriptionFull:
      "Художник намеренно уходит здесь от плотной, пастозной живописи, к которой привык: краска положена тонко и сухо, почти втёрта в холст, и фигура кажется написанной темперой по левкасу — не столько написанной, сколько проступившей. Контур ведён мягкой линией и сам по себе почти графичен: плечи, локти, колени очерчены одним движением. Цвет сведён к перламутровому — розовое, палевое, серо-зелёное фона, — и лишь золото волос звучит чуть громче. Лицо написано подробнее всего остального: большие светлые глаза смотрят прямо, выражение спокойное и слегка отстранённое. От постановочного этюда здесь не осталось ничего — это портрет, только без одежды, и в нём есть та целомудренная тишина, которая встречается в старой русской живописи начала века. Крупный вертикальный формат работает на образ, делая фигуру хрупкой и высокой.",
